export type ObservationStatus = "ok" | "error";
export type ObservationSeverity = "debug" | "info" | "warn" | "error";

export interface ObservationLogger {
  debug?(message: string, context?: Record<string, unknown>): void;
  info?(message: string, context?: Record<string, unknown>): void;
  warn?(message: string, context?: Record<string, unknown>): void;
  error?(message: string, context?: Record<string, unknown>): void;
}

export interface ObservationScope {
  service?: string;
  component?: string;
  labels?: Record<string, string>;
}

export interface ObservationMetric {
  kind: string;
  operation: string;
  component?: string;
  resource?: string;
  labels?: Record<string, string>;
  durationMs?: number;
  ok?: boolean;
}

export interface ObservationEvent<
  TDomain extends string = string,
  TType extends string = string,
  TMetadata extends Record<string, unknown> = Record<string, unknown>,
> {
  domain: TDomain;
  type: TType;
  severity?: ObservationSeverity;
  component?: string;
  requestId?: string;
  actorId?: string;
  subjectId?: string;
  userId?: string;
  outcome?: string;
  metadata?: TMetadata;
}

export interface ObservationSpanInput {
  kind: string;
  operation: string;
  component?: string;
  resource?: string;
  labels?: Record<string, string>;
}

export interface ObservationSpan {
  end(input?: { ok?: boolean; labels?: Record<string, string> }): void;
}

export interface RequestObservationInput {
  request?: Request;
  requestId?: string;
  method?: string;
  path?: string;
  startTimeMs?: number;
  labels?: Record<string, string>;
}

export interface RequestObservationFinishInput {
  status?: number;
  totalDurationMs?: number;
  labels?: Record<string, string>;
}

export interface ObservationGroupSnapshot {
  kind: string;
  count: number;
  durationMs: number;
  maxDurationMs: number;
  errorCount: number;
}

export interface RequestObservationSnapshot {
  requestId: string;
  method?: string;
  path?: string;
  status?: number;
  totalDurationMs: number;
  labels: Record<string, string>;
  groups: Record<string, ObservationGroupSnapshot>;
