function createStackRequestContext<TEvent extends ObservationEvent>(): RequestObservationContext<TEvent> {
  const stack: RequestObservation<TEvent>[] = [];
  return {
    async run<T>(
      observation: RequestObservation<TEvent>,
      work: () => T | Promise<T>,
    ): Promise<T> {
      stack.push(observation);
      try {
