    return undefined;
  }
}

function logEvent(logger: ObservationLogger | undefined, event: ObservationEvent): void {
  const context = {
    domain: event.domain,
    requestId: event.requestId,
    actorId: event.actorId,
    subjectId: event.subjectId,
    userId: event.userId,
    outcome: event.outcome,
    metadata: event.metadata,
  };
