function observe(
  name: MiddlewareName,
  middleware: MiddlewareHandler<ApiEnvironment>,
  observer?: (name: MiddlewareName) => void,
): MiddlewareHandler<ApiEnvironment> {
  return async (context, next) => {
    observer?.(name);
