            fencingEpoch,
            metadata: {
              method: context.req.method,
              requestedAction: action,
              route: routePath(context) || "unmatched",
            },
          });
        } catch {
          throw new DomainError(
            "AUDIT_WRITE_FAILED",
            "The authorization decision could not be recorded",
            503,
          );
        }
        throw error;
      }
      context.set("principal", principal);
    }
