  const auth = resolveAuth(config);
  const fetchImpl = config.fetchImpl ?? globalThis.fetch;
  const retries = config.retries ?? 1;
  const retryDelayMs = config.retryDelayMs ?? 150;
  const timeoutMs = config.timeoutMs ?? 8_000;

