          error instanceof RuntimeError &&
          [
            "SKILL_NOT_FOUND",
            "SKILL_VERSION_NOT_FOUND",
            "NOT_FOUND",
            "VALIDATION_FAILED",
            "USAGE_SCOPE_INVALID",
            "IDEMPOTENCY_KEY_REUSED",
