export interface AccountProfile {
  alias: string;
  endpoint: string;
  accountId: string;
  credentialRef: string;
}
export class Profiles {
  constructor(
    readonly store: LocalStore,
    readonly secrets: SecretStore = new OsSecretStore(),
  ) {}
