      throw new RuntimeError("DOWNLOAD_ORIGIN_INVALID");
    try {
      const response = await fetch(url, {
        headers: { Authorization: `Bearer ${await this.token()}` },
        redirect: "error",
        signal: AbortSignal.timeout(15000),
      });
      if (!response.ok || !response.body) throw new RuntimeError("CLOUD_UNAVAILABLE");
      const reader = response.body.getReader();
      const chunks: Uint8Array[] = [];
      let size = 0;
      try {
        for (;;) {
          const { done, value } = await reader.read();
          if (done) break;
          size += value.length;
          if (size > max) throw new RuntimeError("ASSET_TOO_LARGE");
          chunks.push(value);
        }
      } finally {
        await reader.cancel().catch(() => undefined);
      }
      return Buffer.concat(chunks);
    } catch (error) {
      if (error instanceof RuntimeError) throw error;
      throw new RuntimeError("CLOUD_UNAVAILABLE", "Asset download failed");
    }
  }
}
export class CloudWorkspaceProvider implements WorkspaceProvider {
  constructor(
    readonly workspace: Extract<
      WorkspaceRef,
      {
        provider: "cloud";
      }
    >,
    readonly transport: CloudTransport,
    readonly caller: CallerDeclaration = declaredCaller(),
  ) {}
  static fromProfiles(
    workspace: Extract<
      WorkspaceRef,
      {
        provider: "cloud";
      }
    >,
    profiles: Profiles,
    caller = declaredCaller(),
  ): CloudWorkspaceProvider {
    const profile = profiles.get(workspace.profile, workspace.endpoint);
    return new CloudWorkspaceProvider(
      workspace,
      new McpTransport(workspace.endpoint, () =>
        profiles.secrets.get(profile.credentialRef),
      ),
      caller,
    );
  }
  private call(name: string, args: Record<string, unknown>): Promise<unknown> {
    return this.transport.call(name, { ...args, caller: this.caller });
  }
  async list(): Promise<SkillInfo[]> {
    const items: SkillInfo[] = [];
    let cursor: string | null = null;
    const seen = new Set<string>();
    do {
      const page = skillsListOutputSchema.parse(
        await this.call("skills_list", {
          workspace: { id: this.workspace.id },
          limit: 100,
          cursor,
        }),
      );
      if (
        page.workspace.id !== this.workspace.id ||
        page.skills.some((s) => s.workspaceId !== this.workspace.id)
      )
        throw new RuntimeError("WORKSPACE_MISMATCH");
      items.push(
        ...page.skills.map((s) => ({
          id: s.id,
          slug: s.slug,
          name: s.name,
          description: s.summary,
        })),
      );
      cursor = page.nextCursor;
      if (cursor && seen.has(cursor)) throw new RuntimeError("PAGINATION_INVALID");
      if (cursor) seen.add(cursor);
    } while (cursor);
    return items;
  }
  async versions(skillId: string): Promise<VersionInfo[]> {
    // Check membership in this exact workspace before ID-only MCP operations.
    if (!(await this.list()).some((s) => s.id === skillId))
      throw new RuntimeError("SKILL_NOT_FOUND");
    const items: VersionInfo[] = [];
    let cursor: string | null = null;
    const seen = new Set<string>();
    do {
      const page = skillVersionsListOutputSchema.parse(
        await this.call("skill_versions_list", {
          skill: { id: skillId },
          limit: 100,
          cursor,
        }),
      );
      if (page.skillId !== skillId) throw new RuntimeError("SKILL_MISMATCH");
      items.push(...page.versions);
      cursor = page.nextCursor;
      if (cursor && seen.has(cursor)) throw new RuntimeError("PAGINATION_INVALID");
      if (cursor) seen.add(cursor);
    } while (cursor);
    return items;
  }
  async retrieve(skillId: string, versionId?: string): Promise<Snapshot> {
    const output = skillRetrieveOutputSchema.parse(
      await this.call("skill_retrieve", {
        skill: { id: skillId },
        version: versionId
          ? { selector: "versionId", versionId }
          : { selector: "current" },
      }),
    );
    if (
      output.skill.workspaceId !== this.workspace.id ||
      output.skill.id !== skillId ||
      (versionId && output.version.id !== versionId)
    )
      throw new RuntimeError("WORKSPACE_MISMATCH");
    const files = new Map<string, Uint8Array>([
      ["SKILL.md", Buffer.from(output.instructions)],
    ]);
    for (const descriptor of output.files) {
      if (descriptor.path === "SKILL.md") continue;
      const asset = skillAssetRetrieveOutputSchema.parse(
        await this.call("skill_asset_retrieve", {
          skill: { id: skillId },
          version: { selector: "versionId", versionId: output.version.id },
          path: descriptor.path,
        }),
      );
      if (
        asset.skillId !== skillId ||
        asset.versionId !== output.version.id ||
        asset.path !== descriptor.path ||
        asset.bundleDigest !== output.version.digest
      )
        throw new RuntimeError("ASSET_IDENTITY_MISMATCH");
      const max = Math.min(descriptor.byteSize, 5 * 1024 * 1024);
      if (
        descriptor.byteSize > max ||
        (asset.delivery === "text" &&
          Buffer.byteLength(requireValue(asset.text), "utf8") > max) ||
        (asset.delivery === "base64" &&
          requireValue(asset.base64).length > 4 * Math.ceil(max / 3))
      )
        throw new RuntimeError("ASSET_TOO_LARGE");
      const bytes =
        asset.delivery === "text"
          ? Buffer.from(requireValue(asset.text))
          : asset.delivery === "base64"
            ? Buffer.from(requireValue(asset.base64), "base64")
            : await this.transport.download(
                requireValue(asset.url),
                Math.min(descriptor.byteSize, 5 * 1024 * 1024),
              );
      if (hash(bytes) !== descriptor.sha256 || bytes.length !== descriptor.byteSize)
        throw new RuntimeError("DIGEST_MISMATCH");
      files.set(descriptor.path, bytes);
    }
    const immutableSkill = skillJsonSchema.parse(
      JSON.parse(new TextDecoder().decode(files.get("skill.json"))),
    );
    const bundle = await canonicalizeBundleFiles({ skill: immutableSkill, files });
    if (bundle.digest !== output.version.digest)
      throw new RuntimeError("DIGEST_MISMATCH");
    return {
      workspace: this.workspace,
      skill: {
        id: output.skill.id,
        slug: immutableSkill.slug,
        name: immutableSkill.name,
        description: immutableSkill.description,
      },
      version: output.version,
      bundle,
    };
  }
  async reportUsage(
    event: UsageEvent,
    membership?: ReadonlySet<string>,
  ): Promise<string> {
    if (
      event.workspace !== workspaceKey(this.workspace) ||
      event.type === "skill_success_verified"
    )
      throw new RuntimeError("USAGE_SCOPE_INVALID");
    if (
      !(membership ?? new Set((await this.list()).map((skill) => skill.id))).has(
        event.skillId,
      )
    )
      throw new RuntimeError("SKILL_NOT_FOUND");
    const {
      id,
      timestamp,
      type,
      installationId,
      agent,
      model,
      sessionId,
      delivery,
      freshness,
    } = event;
    const output = skillUsageReportOutputSchema.parse(
      await this.call("skill_usage_report", {
        skill: { id: event.skillId },
        versionId: event.versionId,
        event: {
          id,
          timestamp,
          type,
          installationId,
          agent,
          model,
          sessionId,
          delivery,
          freshness,
        },
      }),
    );
    if (output.acceptedId !== id) throw new RuntimeError("ANALYTICS_ACK_INVALID");
    return id;
  }
  async create(request: CreateRequest): Promise<{
    skillId: string;
    versionId: string;
  }> {
    const output = skillCreateOutputSchema.parse(
      await this.call("skill_create", {
        ...request,
        workspace: { id: this.workspace.id },
      }),
    );
    if (output.skill.workspaceId !== this.workspace.id)
      throw new RuntimeError("WORKSPACE_MISMATCH");
    return { skillId: output.skill.id, versionId: output.version.id };
  }
  async amend(request: AmendRequest): Promise<{
    skillId: string;
    versionId: string;
  }> {
    await this.retrieve(request.skillId, request.baseVersionId);
    const output = skillAmendOutputSchema.parse(
      await this.call("skill_amend", request),
    );
    if (
      output.skillId !== request.skillId ||
      output.baseVersionId !== request.baseVersionId
    )
      throw new RuntimeError("SKILL_MISMATCH");
    return { skillId: output.skillId, versionId: output.candidate.id };
  }
  async candidates(skillId: string): Promise<unknown> {
    if (!(await this.list()).some((s) => s.id === skillId))
      throw new RuntimeError("SKILL_NOT_FOUND");
    let cursor: string | null = null;
    const items = [];
    const seen = new Set<string>();
    do {
      const page = skillCandidatesListOutputSchema.parse(
        await this.call("skill_candidates_list", {
          skill: { id: skillId },
          limit: 100,
          cursor,
        }),
      );
      if (page.skillId !== skillId) throw new RuntimeError("SKILL_MISMATCH");
      items.push(...page.candidates);
      cursor = page.nextCursor;
      if (cursor && seen.has(cursor)) throw new RuntimeError("PAGINATION_INVALID");
      if (cursor) seen.add(cursor);
    } while (cursor);
    return items;
  }
  async decide(
    skillId: string,
    reviewId: string,
    expectedUpdatedAt: string,
    approve: boolean,
    reason: string,
    idempotencyKey: string,
  ): Promise<unknown> {
    if (!(await this.list()).some((s) => s.id === skillId))
      throw new RuntimeError("SKILL_NOT_FOUND");
    const output = skillCandidateDecisionOutputSchema.parse(
      await this.call(approve ? "skill_candidate_approve" : "skill_candidate_reject", {
        skill: { id: skillId },
        reviewId,
        expectedUpdatedAt,
        reason,
        idempotencyKey,
      }),
    );
    if (output.skillId !== skillId) throw new RuntimeError("SKILL_MISMATCH");
    return output;
  }
}

import { build } from "esbuild";
import { chmodSync } from "node:fs";
await build({
  entryPoints: ["src/cli.ts"],
  outfile: "dist/skillplane.mjs",
  bundle: true,
  platform: "node",
  format: "esm",
  target: "node22",
  conditions: ["development"],
  banner: {
    js: "import { createRequire as skillplaneCreateRequire } from 'node:module'; const require = skillplaneCreateRequire(import.meta.url);",
  },
});
chmodSync("dist/skillplane.mjs", 0o755);
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { execFileSync, spawnSync } from "node:child_process";
import {
  mkdtempSync,
  rmSync,
  realpathSync,
  writeFileSync,
  readFileSync,
  mkdirSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const packageRoot = resolve(import.meta.dirname, "..");
const roots: string[] = [];
afterAll(() => {
  for (const root of roots) rmSync(root, { recursive: true, force: true });
});
const cli = resolve(packageRoot, "dist/skillplane.mjs");
beforeAll(() => {
  execFileSync(process.execPath, ["build.mjs"], { cwd: packageRoot });
});
describe("packaged global CLI", () => {
  it("installs and completes offline initialization, creation, invocation, export and diagnostics", () => {
    const root = realpathSync(mkdtempSync(join(tmpdir(), "skillplane-cli-")));
    roots.push(root);
    const project = join(root, "project");
    mkdirSync(project);
    const bin = join(root, "bin");
    execFileSync(process.execPath, [
      resolve(packageRoot, "../../scripts/install-local-client.mjs"),
      bin,
    ]);
    const installed = join(bin, "skillplane");
    const run = (...args: string[]) =>
      JSON.parse(
        execFileSync(
          process.execPath,
          [installed, ...args, "--home", join(root, "state"), "--project", project],
          { encoding: "utf8" },
        ),
      );
    const config = run("init", "Offline", "--target", "codex");
    expect(config.primary.provider).toBe("local");
    const file = join(root, "create.json");
    writeFileSync(
      file,
      JSON.stringify({
        slug: "read",
        name: "Read",
        instructions: "Read the supplied document.",
        idempotencyKey: "create",
      }),
    );
    const created = run("create", file);
    expect(created.skillId).toMatch(/^skill:/);
    const records = run("sync");
    expect(records).toHaveLength(1);
    const record = records[0];
    const resolved = run("resolve", record.id, "--agent", "codex");
    expect(resolved.useEmbedded).toBe(true);
    expect(resolved.instructions).toBeUndefined();
    expect(run("doctor").projections[0].health).toBe("healthy");
    expect(run("usage").uploadEnabled).toBe(false);
    const archive = join(root, "export.zip");
    run("export", created.skillId, archive);
    expect(readFileSync(archive).length).toBeGreaterThan(0);
    run("uninstall", record.id);
    expect(run("doctor").projections).toHaveLength(0);
    const overwrite = spawnSync(process.execPath, [
      resolve(packageRoot, "../../scripts/install-local-client.mjs"),
      bin,
    ]);
    expect(overwrite.status).not.toBe(0);
  });
  it("help and validation errors work without service dependencies or secret output", () => {
    expect(
      execFileSync(process.execPath, [cli, "--help"], { encoding: "utf8" }),
    ).toContain("Skillplane local and cloud");
    const root = realpathSync(mkdtempSync(join(tmpdir(), "skillplane-invalid-")));
    const result = spawnSync(
      process.execPath,
      [cli, "resolve", "missing", "--home", root],
      { encoding: "utf8" },
    );
    expect(result.status).toBe(1);
    expect(result.stderr).toContain("projection_not_found");
  });
});

