const DEFAULT_TIMEOUT_MS = 30_000;
const DEFAULT_MAX_BUFFER_BYTES = 1_048_576;
const DEFAULT_TIMEOUT_GRACE_MS = 250;

export type ExecErrorCode = "CLIFN_EXEC_TIMEOUT";

export interface ExecOptions {
