    11	function command(program: string, args: string[], input?: string): Promise<string> {
    12	  return new Promise((resolve, reject) => {
    13	    const child = spawn(program, args, { stdio: ["pipe", "pipe", "pipe"] });
    14	    let output = "";
    15	    child.stdout.on("data", (chunk) => {
    16	      output += String(chunk);
    17	    });
    18	    child.on("error", () => reject(new RuntimeError("SECRET_SERVICE_UNAVAILABLE")));
    19	    child.on("close", (code) =>
    20	      code === 0
    21	        ? resolve(output.trimEnd())
    22	        : reject(new RuntimeError("CREDENTIAL_UNAVAILABLE")),
    23	    );
    24	    child.stdin.end(input);
    25	  });
    26	}
